package app

import (
	"strings"
	"testing"

	"github.com/TokenFlux/TokenRouter/internal/config"
)

// Payment encryption can use a configured persistent TOTP key but cannot rely
// on an automatically generated key. The assembly tests exercise both
// configuration states and a short configured key, checking disabled
// encryption, decoded byte length, and startup validation failure.

// TestProvidePaymentEncryptionKeySkipsAutoGeneratedTotpKey supplies a
// valid-looking key marked as automatically generated. It checks assembly
// succeeds with no payment encryption bytes, protecting persistent key identity
// requirements.
func TestProvidePaymentEncryptionKeySkipsAutoGeneratedTotpKey(t *testing.T) {
	t.Parallel()

	cfg := &config.Config{Security: config.SecurityConfig{
		SecretEncryptionKey:           strings.Repeat("a", 64),
		SecretEncryptionKeyConfigured: false,
	}}

	key, err := providePaymentEncryptionKey(cfg)
	if err != nil {
		t.Fatalf("providePaymentEncryptionKey returned error: %v", err)
	}
	if len(key) != 0 {
		t.Fatalf("encryption key len = %d, want 0", len(key))
	}
}

// TestProvidePaymentEncryptionKeyUsesConfiguredTotpKey supplies a configured
// sixty-four-character hex key. It checks assembly succeeds and decodes
// thirty-two encryption bytes for the payment runtime.
func TestProvidePaymentEncryptionKeyUsesConfiguredTotpKey(t *testing.T) {
	t.Parallel()

	cfg := &config.Config{Security: config.SecurityConfig{
		SecretEncryptionKey:           "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef",
		SecretEncryptionKeyConfigured: true,
	}}

	key, err := providePaymentEncryptionKey(cfg)
	if err != nil {
		t.Fatalf("providePaymentEncryptionKey returned error: %v", err)
	}
	if len(key) != 32 {
		t.Fatalf("encryption key len = %d, want 32", len(key))
	}
}

// TestProvidePaymentEncryptionKeyRejectsConfiguredInvalidLength supplies a
// configured short hex key. It checks assembly returns a validation error,
// preventing invalid persistent key bytes from reaching payment encryption.
func TestProvidePaymentEncryptionKeyRejectsConfiguredInvalidLength(t *testing.T) {
	t.Parallel()

	cfg := &config.Config{Security: config.SecurityConfig{
		SecretEncryptionKey:           "abcd",
		SecretEncryptionKeyConfigured: true,
	}}

	_, err := providePaymentEncryptionKey(cfg)
	if err == nil {
		t.Fatal("expected error for invalid key length")
	}
}
